#include "cguildwarehousedialog.hpp"
namespace mxh::ui{static bool valid(WarehouseItem x){return x.item_id!=0&&x.quantity!=0;}bool cGuildWarehouseDialog::Store(std::size_t s,WarehouseItem x){if(m_locked||!m_can_store||s>=kSlots||m_items[s]||!valid(x))return false;m_items[s]=x;return true;}std::optional<WarehouseItem> cGuildWarehouseDialog::Take(std::size_t s){if(m_locked||!m_can_take||s>=kSlots||!m_items[s])return std::nullopt;auto x=m_items[s];m_items[s].reset();return x;}bool cGuildWarehouseDialog::Move(std::size_t f,std::size_t t){if(m_locked||!m_can_store||!m_can_take||f>=kSlots||t>=kSlots||f==t||!m_items[f]||m_items[t])return false;std::swap(m_items[f],m_items[t]);return true;}}
